// CatalogAdminServiceHandler is an implementation of the kuepreorder.catalog.v1.CatalogAdminService
// service.
type CatalogAdminServiceHandler interface {
	ListProducts(context.Context, *connect.Request[v1.ListProductsRequest]) (*connect.Response[v1.ListProductsResponse], error)
	CreateProduct(context.Context, *connect.Request[v1.CreateProductRequest]) (*connect.Response[v1.CreateProductResponse], error)
	UpdateProduct(context.Context, *connect.Request[v1.UpdateProductRequest]) (*connect.Response[v1.UpdateProductResponse], error)
	ListVariants(context.Context, *connect.Request[v1.ListVariantsRequest]) (*connect.Response[v1.ListVariantsResponse], error)
	CreateVariant(context.Context, *connect.Request[v1.CreateVariantRequest]) (*connect.Response[v1.CreateVariantResponse], error)
	// UpdateVariant changes everything but the product and the price.
	UpdateVariant(context.Context, *connect.Request[v1.UpdateVariantRequest]) (*connect.Response[v1.UpdateVariantResponse], error)
	// ChangeVariantPrice is the only way to change a price. It needs a reason
	// and is audited: who, when, from what, to what, and why (§22).
	ChangeVariantPrice(context.Context, *connect.Request[v1.ChangeVariantPriceRequest]) (*connect.Response[v1.ChangeVariantPriceResponse], error)
	ListComponents(context.Context, *connect.Request[v1.ListComponentsRequest]) (*connect.Response[v1.ListComponentsResponse], error)
	CreateComponent(context.Context, *connect.Request[v1.CreateComponentRequest]) (*connect.Response[v1.CreateComponentResponse], error)
	UpdateComponent(context.Context, *connect.Request[v1.UpdateComponentRequest]) (*connect.Response[v1.UpdateComponentResponse], error)
	ListIngredients(context.Context, *connect.Request[v1.ListIngredientsRequest]) (*connect.Response[v1.ListIngredientsResponse], error)
	CreateIngredient(context.Context, *connect.Request[v1.CreateIngredientRequest]) (*connect.Response[v1.CreateIngredientResponse], error)
	UpdateIngredient(context.Context, *connect.Request[v1.UpdateIngredientRequest]) (*connect.Response[v1.UpdateIngredientResponse], error)
	ListSuppliers(context.Context, *connect.Request[v1.ListSuppliersRequest]) (*connect.Response[v1.ListSuppliersResponse], error)
	CreateSupplier(context.Context, *connect.Request[v1.CreateSupplierRequest]) (*connect.Response[v1.CreateSupplierResponse], error)
	UpdateSupplier(context.Context, *connect.Request[v1.UpdateSupplierRequest]) (*connect.Response[v1.UpdateSupplierResponse], error)
	// ListPacks lists how an ingredient is sold, the default pack first.
	ListPacks(context.Context, *connect.Request[v1.ListPacksRequest]) (*connect.Response[v1.ListPacksResponse], error)
	CreatePack(context.Context, *connect.Request[v1.CreatePackRequest]) (*connect.Response[v1.CreatePackResponse], error)
	UpdatePack(context.Context, *connect.Request[v1.UpdatePackRequest]) (*connect.Response[v1.UpdatePackResponse], error)
	// SetDefaultPack makes a pack the one the shopping list rounds to.
	SetDefaultPack(context.Context, *connect.Request[v1.SetDefaultPackRequest]) (*connect.Response[v1.SetDefaultPackResponse], error)
	ListVariantComponents(context.Context, *connect.Request[v1.ListVariantComponentsRequest]) (*connect.Response[v1.ListVariantComponentsResponse], error)
	// SetVariantComponents replaces all components of a variant at once.
	SetVariantComponents(context.Context, *connect.Request[v1.SetVariantComponentsRequest]) (*connect.Response[v1.SetVariantComponentsResponse], error)
	ListRecipeLines(context.Context, *connect.Request[v1.ListRecipeLinesRequest]) (*connect.Response[v1.ListRecipeLinesResponse], error)
	// SetRecipeLine creates or replaces how much of an ingredient a component
	// needs, from params or from measured points. The recipe engine checks it
	// first; a bad formula is InvalidArgument on params_json or points.
	SetRecipeLine(context.Context, *connect.Request[v1.SetRecipeLineRequest]) (*connect.Response[v1.SetRecipeLineResponse], error)
	RemoveRecipeLine(context.Context, *connect.Request[v1.RemoveRecipeLineRequest]) (*connect.Response[v1.RemoveRecipeLineResponse], error)
	// FitPreview fits every fittable model to measured points for a chart,
	// without saving anything.
	FitPreview(context.Context, *connect.Request[v1.FitPreviewRequest]) (*connect.Response[v1.FitPreviewResponse], error)
}

